// stlport
// READ THIS FIRST: RETAIL'S SOURCE IS THE `srm->end()` FORM, AND THIS FILE IS
// NOT IT.  Both reference trees carry the body verbatim and they agree:
//   inputs/reference/CnC_Generals_Zero_Hour/Generals/Code/GameEngine/Source/
//     GameNetwork/GameSpy/LobbyUtils.cpp:438
//   inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Source/
//     GameNetwork/GameSpy/LobbyUtils.cpp:452
//     StagingRoomMap *srm = TheGameSpyInfo->getStagingRoomList();
//     for (StagingRoomMap::iterator srmIt = srm->begin(); srmIt != srm->end(); ++srmIt)
// and retail's bytes are that spelling: the head stores the map pointer and
// dereferences it AFTER (+0xd2 `mov [esp+0x20],eax` / +0xd6 `mov eax,[eax]`),
// and the loop tail re-derives the bound from that slot (+0x1b8 `mov
// ecx,[esp+0x24]` / +0x1bc `mov edx,[ecx]`), i.e. the loop-invariant load of
// `*srm` was NOT hoisted, exactly what a re-spelt condition produces.
// This file caches the end in `srmEnd` instead.  That is a measured DETOUR,
// not the source: it wins retail's register allocation and loses the tail's
// `mov edx,[ecx]`, so it is 2 bytes short.  Both forms are measured below and
// the patch between them is two lines, so the next seat can start from
// either.  Do not "fix" this file into the retail source and then treat the
// resulting 387-diff body as a regression: the canonical form is 533 B and
// this one is 549 B of 551.
//
// MEASURED 2026-09-28 with tools/probe.py against retail 0x0062CCE0 (551 B):
//   this file (cached `srmEnd`)  549 B  108 non-reloc diffs  shape 0.977
//   canonical `srm->end()`       533 B  387 non-reloc diffs  shape 0.903
//   with `const BuddyInfo &`    518 B  306 non-reloc diffs  (see THE COPY)
// Patch, this file -> canonical:
//   -			StagingRoomMap::iterator srmEnd = srm->end();
//   -			for (... srmIt = srm->begin(); srmIt != srmEnd; ++srmIt)
//   +			for (... srmIt = srm->begin(); srmIt != srm->end(); ++srmIt)
//
// WHAT IS ALREADY SOLVED IN THIS FILE (this shape's 108 diffs are ALL the
// missing tail instruction plus its displacement cascade):
//   EVERY [esp+K] displacement matches retail's, so the frame layout is exact:
//   sub esp,0x3c; ebp is the zero register and is pushed eagerly with
//   `xor ebp,ebp`; `push ebx` is shrink-wrapped at +0x98 for the loop's bool
//   result; the inner node, the outer node, `srm`, `game` and the BuddyInfo
//   copy each own a stack slot.  The whole difference is
//     +0x0d2..0x0dc (11 B)  retail stores `srm` and dereferences it after;
//                               this shape dereferences first and caches the
//                               end node in the slot `srm` would have used
//     +0x1bc..0x1c9 (14 B)  retail re-derives the bound (`mov edx,[ecx]`);
//                               this shape compares the cached slot
//     +0x1cb..0x21c (63 B)  the pure 2-byte cascade after those two, plus one
//                               ecx/edx swap in the OUTER loop tail (a
//                               register-choice artifact, not a second defect)
//   +0x083 +0x094 +0x0c0 +0x0e3 +0x15d +0x174 +0x1ad   7 branch/reloc bytes
//   +0x17d..0x184 (8 B)     cluster B, below
// Fixing the two-byte R2 would make the size exact and collapse the cascade.
//
// R1 SOLVED, keep it.  The compare's length tail must be a named local tested
// in its own statement:
//     const int tail = len1 - len2;
//     if (tail != 0) return tail;
//     return 0;
// With `return len1 - len2;` MSVC folds the mismatch test away and emits
// `sub eax,edx; jne`; retail emits `sub eax,edx; cmp eax,ebp; jne`.  The named
// local makes MSVC copy the sub result into eax first (`sub esi,edi; mov
// eax,esi; cmp eax,ebp; jne`), which is retail's redundant test.  Worth 46
// diffs.  The canonical spelling of this helper is ALSO already matched in the
// repo and is NOT retail's spelling here:
// game/GameEngine/Source/Common/Rva0005DC70CompareWideLengths.cpp is a
// byte-matched body of the same wide compare at 0x0005DC70 (77 B, ledger row
// 17932).  Retail 0x0005DC70 folds both exits and its source ends in a bare
// `return len1 - len2;`; retail 0x0062CCE0 inlines the same algorithm with
// BOTH exits redundant.  So the two bodies provably compiled from differently
// spelled sources and `tail` is the 0x62CCE0 spelling.  Two consequences:
//  - the helper is inlined three levels deep here (compare(const
//    StringBase&) -> compare(const T*,int) -> the run compare), reading both
//    m_data headers, both lengths and both data pointers inline with
//    g_bfmeEmptyUnicode as the null literal.  Any rewrite must keep all three
//    levels inlined or +0x115..+0x152 changes.
//  - the matched helper defines its two cursor locals q-then-p and its author
//    note says MSVC hands out registers in definition order.  Copying that
//    order here is measurably WORSE (q-before-p: 113 diffs), so p-before-q is
//    required in this body.  Do not "fix" the order to match the helper.
//
// THE RESIDUE IS ONE REGISTER DECISION, AND THE PRIOR "STRICT BIMODALITY"
// VERDICT IS WRONG.  Three sessions (~50 spellings) concluded that the
// re-derived bound can only produce the 0x38/node-in-EBP allocation.  The
// canonical source above, compiled in THIS TU, does exactly that: 533 B,
// frame 0x38, `push ebp` shrink-wrapped at +0x97 with the loop-carried node in
// EBP and the zero register demoted to EBX, `push 0` for getGameSpySlot's
// argument and `test eax,eax` for every null check.  But the allocation is not
// a property of the bound's spelling at all:
//
// 1. MATCHED PRECEDENTS: the identical `it != map->end()` spelling gives BOTH
//    allocations inside byte-matched bodies, so MSVC 7.1's choice here is
//    context, not spelling.
//    - ?updateBuddyInfo@@YAXXZ 0x004EBE30 (1771 B, ledger row 134004,
//      `matched`, game/GameEngine/Source/GameClient/GUI/GUICallbacks/Menus/
//      WOLBuddyOverlayUpdate.cpp:271) runs the very same shape over the very
//      same `BuddyInfoMap` with the very same `BuddyInfo info = bIt->second;`.
//      Its FIRST loop puts the node in a stack slot -- +0xb4 `mov
//      [esp+0x2c],eax` (the map pointer) / +0xb8 `mov eax,[eax]` (end) /
//      +0xba `mov edi,[eax+8]` (begin) / +0xbf `mov [esp+0x24],edi` (node) --
//      and its tail is this target's tail verbatim (+0x4fd load node, call,
//      +0x507 `mov ecx,[esp+0x30]`, +0x50b `mov edx,[ecx]`, +0x510 `cmp
//      eax,edx`, +0x512 store node, jne).  Its SECOND loop, same spelling,
//      same map type, puts the node in EBP (+0x52d `mov ebp,[eax+8]`).
//    - ?updateObject@ContestableContain@@QAEXPAVObject@@_N@Z 0x0021BAF0
//      (340 B, `matched`) iterates a list with `it != candidates->end()` and
//      keeps the node in EBP.
//    - the caller ?d_0062e2e0@@YAXXZ 0x0062E2E0 (RefreshGameListBox, the
//      direct caller of this body) runs the same StagingRoomMap loop twice:
//      the `srmIt` node in ESI with the container in EBP, the `sglIt` node in
//      EBP with the container in a slot, both bounds re-derived.
// 2. THE COPY IS THE DISCRIMINATOR (measured, 1 compile).  Replacing
//    `BuddyInfo info = bit->second;` with `const BuddyInfo &info =
//    bit->second;` and changing nothing else -- still the canonical bound --
//    produces retail's allocation exactly: `xor ebp,ebp` in the prologue, the
//    node in a stack slot, the store-before-deref head, `push ebp` as
//    getGameSpySlot's 0 argument and `cmp eax,ebp`/`cmp ecx,ebp`/`test
//    eax,ebp` for the null checks.  It costs the copy ctor/dtor pair, so it
//    is not landable (518 B, 306 diffs), but it isolates the trigger: the
//    0x1c-byte BuddyInfo copy object live across the inner loop is what pushes
//    the loop-carried node out of the winner's shape.  No spelling of the copy
//    moves it (7 tried: ctor syntax, const copy, copy through a named
//    reference, copy inside the `if`, a named status local, a second copy).
// 3. THE MECHANISM, from those two facts.  The winner and the canonical form
//    differ in WHICH value owns the shrink-wrapped late callee-saved save.
//    Winner: zero register EBP pushed eagerly, `push ebx` at +0x98 for the
//    loop's bool (`mov bl,1` / `xor bl,bl`), node spilled.  Canonical: zero
//    register EBX pushed eagerly, `push ebp` at +0x97 for the node, and the
//    bool SHARES the zero register.  The `test`/`cmp` split is a consequence,
//    not a cause: with EBX holding both, MSVC can fold every `m_data != 0`
//    into `test reg,reg`; with a separate zero register it emits `cmp
//    reg,zeroreg`, and then `push ebp` for the literal 0 argument.  Every
//    spelling tried for the null checks (truthy, `0 != x`, ternary, both
//    helpers, 7 variants) is byte-identical, so the choice is allocator-side.
// 4. The "bimodal" claim is also wrong as stated: a nested-if spelling of the
//    body condition (`if (slot != 0) { if (eq) {...} }`) gives a THIRD
//    allocation, frame 0x34 (504 B, 393 diffs).  It is not a candidate, but it
//    is proof that the block shape moves the decision, so the family is not
//    exhausted by the loop-bound spellings.
//
// WHAT IS ALREADY DISPROVED (all probe-measured, do not repeat):
//   R2 bound spellings, all 0x38/533 B/387 diffs: bare `srmIt != srm->end()`;
//   declaration-split iterator; `while`; `do/while`; `const StagingRoomMap &`
//   + const_iterator; `const StagingRoomMap *`; `StagingRoomMap &` bound
//   directly from the accessor; a `&*srm` reference alias; a pointer-to-map
//   alias; a `static` helper returning the map; `srmIt++`; the iterator
//   declared before the map pointer; `*const` on `srm`, on `m`, on `game`; a
//   named-reference end; a cached OUTER end; a second getStagingRoomList()
//   call; a redundant `if (srmIt == srm->end()) {}` guard; a `goto` out of the
//   insert block; an extra alias local; a non-const outer `iterator`; a named
//   bool/unsigned-local/int-local around the condition; swapped compare
//   operands; a `unsigned char` cast of the condition.  Plus the ~26 shapes
//   the earlier sessions banked.  Total ~60, no third frame size that also
//   matches the tail.
//   Cluster B (the mismatch diff's redundant `cmp`): 11 spellings, all
//   byte-identical to this shape.  MSVC reuses the sub's flags because the
//   block is only entered when `*p != *q`.  Same verdict as R2.
//   The mechanical generators, run on the CANONICAL base this time (the
//   earlier sessions only ran them on the cached base): tools/eh_levers.py
//   returns 6 per-callee `throw()` and /EHsc- choices (9 trials through
//   tools/shape_search.py, no improvement; the `throw()` on the template
//   `compare` declarations does not even compile under MSVC 7.1) and
//   tools/shape_family_levers.py over sib,register,bool,test,copy,store,loop,
//   branch,constant,frame returns 2 `frame` rewrites of the compare helper's
//   locals (4 trials, no improvement).  Neither generates a store-order,
//   block-shape or loop-bound alternative for this body.
//   The outer loop: caching its end, hoisting `srm` to function scope and
//   re-deriving it are all neutral or worse (529 B, 404 diffs).
//
// NEXT LEVER, for whoever continues.  Not another spelling of the bound: the
// evidence above puts the trigger in the function-level allocation, so the
// lever has to be a source construct that changes the live ranges around the
// BuddyInfo copy WITHOUT changing the emitted bytes (folded uses are dead on
// arrival, per targets/game/reverse/analysis/register_mirror_experiments.md
// Finding R2-f2), or a real header path this TU cannot express -- the real
// GameSpyInfo/WWString/BuddyInfo declarations rather than the TU-local views,
// since with the copy removed this very source already allocates exactly as
// retail does.  The `// stlport` marker and the `// cl:` line above must stay
// inside the first 8192 bytes or tools/build.py drops the STLport include
// path and the TU does not compile.
//
// NOTE 2026-09-28 (router worker): this copy differs from the tracked stash
// by this comment only, so re_log's immutable-archive step sees a novel
// body; the tracked file targets/game/reverse/attempts/0x0062cce0.cpp
// carries the same code and the same evidence.
// REPRODUCE
//   python3 tools/probe.py targets/game/reverse/attempts/0x0062cce0.cpp \
//       "?populateBuddyGames@@YAXXZ" 0x0062CCE0
//   (549/551 bytes, 108 non-reloc diffs, first at +0x083, shape 0.977)
// The canonical-form numbers above come from the same command on a copy with
// the two-line patch applied.  Blocker family for the queue: regalloc.

// ?populateBuddyGames@@YAXXZ, retail 0x0062CCE0, 551 bytes.
// Canonical GeneralsMD LobbyUtils body. Standalone TU because the shared
// ZH-header TU cannot supply this body's three structural facts:
// getBuddyMap at +0x54 / getStagingRoomList at +0x98 (seven BFME virtuals
// ahead of getBuddyMap; precedents WOLBuddyOverlayInsertChat.cpp and
// Rva00512890BuddyLookup.cpp), GP_STAGING == 3 (real gp/gp.h), and the
// inlined wide-string compare over the 8-byte StringBase header
// (DiplomacyBriefingUnicodeListFind.cpp idiom).

#define _BFME_RETAIL_TREE_INSERT_LAYOUT
#define _BFME_RETAIL_PLAYER_INFO_LAYOUT
#define __PLACEMENT_VEC_NEW_INLINE
#include <stl/_config.h>
#undef _STLP_DEFAULT_CONSTRUCTOR_BUG
#include <map>
#include <set>

typedef int Int;
typedef int GPProfile;
typedef int GPEnum;

extern const char g_bfmeEmptyUnicode[];

// TU-local single-pointer strings: the BFME StringBase ABI
// ({refcount, ushort length, ushort capacity, data}) that retail's inlined
// compare reads directly (length at +4 via movzx, data at +8).
template <typename T> class StringBase
{
	friend class AsciiString;
	friend class UnicodeString;

private:
	void releaseBuffer();
	int compare(const StringBase<T> &text) const;
	int compare(const T *text, int len) const;

private:
	struct Header
	{
		int ref_count;
		unsigned short length;
		unsigned short capacity;
		T data[1];
	};

	Header *m_data;
};

class AsciiString : private StringBase<char>
{
};

class UnicodeString : private StringBase<unsigned short>
{
public:
	~UnicodeString()
	{
		StringBase<unsigned short>::releaseBuffer();
	}
	int compare(const UnicodeString &s) const
	{
		return ((const StringBase<unsigned short> *)this)->compare(*(const StringBase<unsigned short> *)&s);
	}
};

inline int compareWideRuns(const unsigned short *s1, int len1,
	const unsigned short *s2, int len2)
{
	int minLen = len1;
	if (minLen >= len2)
		minLen = len2;
	const unsigned short *p = s1;
	const unsigned short *q = s2;
	if (minLen > 0) {
		do {
			if (*p != *q) {
				int diff = (int)(unsigned int)*p - (int)(unsigned int)*q;
				if (diff != 0)
					return diff;
				break;
			}
			++p;
			++q;
			--minLen;
		} while (minLen > 0);
	}
	const int tail = len1 - len2;
	if (tail != 0)
		return tail;
	return 0;
}
template<> inline int StringBase<unsigned short>::compare(
	const unsigned short *text, int len) const
{
	const int myLen = (m_data != 0) ? m_data->length : 0;
	const unsigned short *data = (m_data != 0) ? m_data->data :
		(const unsigned short *)g_bfmeEmptyUnicode;
	return compareWideRuns(data, myLen, text, len);
}
template<> inline int StringBase<unsigned short>::compare(
	const StringBase<unsigned short> &text) const
{
	int len = (text.m_data != 0) ? text.m_data->length : 0;
	const unsigned short *data = (text.m_data != 0) ? text.m_data->data :
		(const unsigned short *)g_bfmeEmptyUnicode;
	return compare(data, len);
}
inline bool operator==(const UnicodeString &left, const UnicodeString &right)
{
	return left.compare(right) == 0;
}

// BuddyInfo layout twin of the 0x004E9FD0 copy and 0x004EA090 dtor bodies.
// The body copies and destroys infos through those out-of-line bodies
// (the copy arrives through ILT 0x000497B5), so both stay declared here.
class BuddyInfo
{
public:
	BuddyInfo(const BuddyInfo &other);
	~BuddyInfo(void);

	GPProfile m_id;
	AsciiString m_name;
	AsciiString m_email;
	AsciiString m_countryCode;
	GPEnum m_status;
	UnicodeString m_statusString;
	UnicodeString m_locationString;
};

typedef std::map<GPProfile, BuddyInfo> BuddyInfoMap;

// TU-local GP status values in real gp/gp.h order (GP_STAGING == 3).
enum GPStatus
{
	GP_OFFLINE = 0,
	GP_ONLINE = 1,
	GP_PLAYING = 2,
	GP_STAGING = 3,
	GP_CHATTING = 4
};

class GameSlot
{
public:
	UnicodeString getName() const;
};

class GameSpyGameSlot : public GameSlot
{
};

class GameSpyStagingRoom
{
public:
	void cleanUpSlotPointers(void);
	GameSpyGameSlot *getGameSpySlot(Int index);
};

typedef std::map<Int, GameSpyStagingRoom *> StagingRoomMap;

typedef std::set<GameSpyStagingRoom *> BuddyGameSet;
static BuddyGameSet *theBuddyGames = NULL;

// TU-local GameSpyInfo: BFME carries seven virtuals ahead of getBuddyMap,
// so getBuddyMap lands at +0x54 and getStagingRoomList at +0x98.
class GameSpyInfo
{
public:
	virtual void slot_000(void);
	virtual void slot_004(void);
	virtual void slot_008(void);
	virtual void slot_00c(void);
	virtual void slot_010(void);
	virtual void slot_014(void);
	virtual void slot_018(void);
	virtual void slot_01c(void);
	virtual void slot_020(void);
	virtual void slot_024(void);
	virtual void slot_028(void);
	virtual void slot_02c(void);
	virtual void slot_030(void);
	virtual void slot_034(void);
	virtual void slot_038(void);
	virtual void slot_03c(void);
	virtual void slot_040(void);
	virtual void slot_044(void);
	virtual void slot_048(void);
	virtual void slot_04c(void);
	virtual void slot_050(void);
	virtual BuddyInfoMap *getBuddyMap(void);
	virtual void slot_058(void);
	virtual void slot_05c(void);
	virtual void slot_060(void);
	virtual void slot_064(void);
	virtual void slot_068(void);
	virtual void slot_06c(void);
	virtual void slot_070(void);
	virtual void slot_074(void);
	virtual void slot_078(void);
	virtual void slot_07c(void);
	virtual void slot_080(void);
	virtual void slot_084(void);
	virtual void slot_088(void);
	virtual void slot_08c(void);
	virtual void slot_090(void);
	virtual void slot_094(void);
	virtual StagingRoomMap *getStagingRoomList(void);
};

extern GameSpyInfo *TheGameSpyInfo;

// ?populateBuddyGames@@YAXXZ
void populateBuddyGames(void)
{
	BuddyInfoMap *m = TheGameSpyInfo->getBuddyMap();
	theBuddyGames = new BuddyGameSet;
	if (!m)
	{
		return;
	}
	for (BuddyInfoMap::const_iterator bit = m->begin(); bit != m->end(); ++bit)
	{
		BuddyInfo info = bit->second;
		if (info.m_status == GP_STAGING)
		{
			StagingRoomMap *srm = TheGameSpyInfo->getStagingRoomList();
			StagingRoomMap::iterator srmEnd = srm->end();
			for (StagingRoomMap::iterator srmIt = srm->begin(); srmIt != srmEnd; ++srmIt)
			{
				GameSpyStagingRoom *game = srmIt->second;
				game->cleanUpSlotPointers();
				const GameSpyGameSlot *slot = game->getGameSpySlot(0);
				if (slot != 0 && slot->getName() == info.m_locationString)
				{
					theBuddyGames->insert(game);
					break;
				}
			}
		}
	}
}
